func GitCommit(t *testing.T, repoDir, message string) {
	t.Helper()

	repo, err := gitrepo.OpenPath(repoDir)
	if err != nil {
		t.Fatalf("failed to open git repo: %v", err)
	}
	defer repo.Close()

	worktree, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
